//! The windowed game's own UI (plain bevy_ui): the main menu and map list, the in-game toolbar and catalog, the
//! settings and control pages, the pause menu. What it offers comes from the original's definitions
//! (`tables.rs`, generated by scripts/gen_ui_tables.py); what the rewrite cannot do yet is shown disabled or marked.

mod data;
mod keys;
mod state;
mod tables;
mod view;

use crate::play::{self, Play};
use bevy::{
    input::{
        keyboard::KeyboardInput,
        mouse::{AccumulatedMouseMotion, AccumulatedMouseScroll, MouseScrollUnit},
    },
    picking::hover::{HoverMap, Hovered},
    prelude::*,
    ui::RelativeCursorPosition,
    window::{MonitorSelection, PresentMode, PrimaryWindow, VideoModeSelection, WindowMode},
};
