pub use state::{Mode, Ui};
pub use state::{Controls, Settings};

/// Acts waiting for `apply`.
#[derive(Resource, Default)]
pub struct Queue(Vec<Act>);

/// Where the preferences and the control scheme are saved (next to the executable), and what changed since.
#[derive(Resource)]
pub struct Files {
    dir: PathBuf,
    settings: bool,
    controls: bool,
}

impl Files {
    fn settings_path(&self) -> PathBuf {
        self.dir.join("ppr-preferences.json")
    }
    fn controls_path(&self) -> PathBuf {
        self.dir.join("ppr-controls.json")
    }
}

/// The saved preferences over the game's config.json over the defaults.
pub fn load_settings(game: Option<&std::path::Path>) -> (Settings, Controls, Files) {
    let dir = std::env::current_exe().ok().and_then(|e| e.parent().map(PathBuf::from)).unwrap_or_default();
    let files = Files { dir, settings: false, controls: false };
    let mut settings = Settings::default();
    if let Some(text) = game.and_then(|g| std::fs::read_to_string(g.join("config.json")).ok()) {
        settings.load(&text);
    }
    if let Ok(text) = std::fs::read_to_string(files.settings_path()) {
        settings.load(&text);
    }
    let mut controls = Controls::default();
    if let Ok(text) = std::fs::read_to_string(files.controls_path()) {
        controls.load(&text);
    }
    (settings, controls, files)
}

/// The maps list is read the first time the map selection opens.
pub fn new_ui(game: Option<PathBuf>, mode: Mode, map: Option<String>, item: Option<String>) -> Ui {
    let mut ui = Ui::new(Vec::new(), mode, map, item);
    ui.game = game.unwrap_or_default();
    ui
}

/// The whole UI, and the game's systems that run under it.
pub fn add(app: &mut App) {
    app.init_resource::<Queue>()
        .init_resource::<Fps>()
        .add_systems(Startup, setup)
        .add_systems(
            Update,
            (
                clicks,
                sliders,
                hotkeys,
                typing,
                rebinding,
                apply,
                loading,
                late_catalog,
                scrolling,
                rebuild,
                live,
                save,
                window,
                (world_input, camera, game_frame, play::limb_sprites, play::object_sprites, play::draw).chain().run_if(resource_exists::<Play>),
            )
                .chain(),
        );
}

#[derive(Resource, Default)]
struct Fps {
    frames: u32,
    time: f32,
    shown: u32,
}

fn setup(mut commands: Commands, play: Option<Res<Play>>) {
    let center = play.map_or(Vec3::ZERO, |p| centre(&p.game));
    commands.spawn((
        Camera2d,
        Projection::Orthographic(OrthographicProjection { scale: 0.006, ..OrthographicProjection::default_2d() }),
        Transform::from_translation(center),
    ));
}

/// Where the camera starts: the first person, else the map's center.
pub fn centre(g: &crate::game::Game) -> Vec3 {
    let c = g.limbs.first().map_or([g.BoundingBox.center[0], g.BoundingBox.center[1], 0.0], |l| g.physicals[l.PhysicalBehaviour].transform.position);
    Vec3::new(c[0], c[1], 0.0)
}

/// The pointer is over a UI node.
pub fn over_ui(hover: &HoverMap, nodes: &Query<(), With<Node>>) -> bool {
    hover.values().flat_map(|m| m.keys()).any(|&e| nodes.contains(e))
}

// ---------------------------------------------------------------- input

/// A button press and release on the same widget.
fn clicks(
    mouse: Res<ButtonInput<MouseButton>>,
    buttons: Query<(Entity, &Press, &Hovered)>,
    ui: Res<Ui>,
    mut queue: ResMut<Queue>,
    mut down: Local<Option<Entity>>,
) {
    let hovered = || buttons.iter().find(|(_, _, h)| h.get());
    if mouse.just_pressed(MouseButton::Left) {
        *down = hovered().map(|(e, _, _)| e);
    }
    // A click anywhere closes the context menu.
    if ui.context.is_some() && (mouse.just_pressed(MouseButton::Left) || mouse.just_pressed(MouseButton::Right)) {
        queue.0.push(Act::Escape);
    }
    if mouse.just_released(MouseButton::Left) {
        if let (Some(d), Some((e, press, _))) = (down.take(), hovered()) {
            if d == e {
                queue.0.push(press.0.clone());
            }
        }
    }
}

/// Dragging a settings slider.
fn sliders(
    mouse: Res<ButtonInput<MouseButton>>,
    tracks: Query<(&SliderOf, &Hovered, &RelativeCursorPosition)>,
    mut settings: ResMut<Settings>,
    mut files: ResMut<Files>,
    mut drag: Local<Option<usize>>,
) {
    if mouse.just_pressed(MouseButton::Left) {
        *drag = tracks.iter().find(|(_, h, _)| h.get()).map(|(s, _, _)| s.0);
    }
    if !mouse.pressed(MouseButton::Left) {
        *drag = None;
    }
    let Some(i) = *drag else { return };
    if let Some((_, _, rel)) = tracks.iter().find(|(s, _, _)| s.0 == i) {
        if let Some(n) = rel.normalized {
            let before = settings.values[i];
            let mut next = settings.clone();
            next.set_fraction(i, n.x + 0.5);
            if next.values[i] != before {
                *settings = next;
                files.settings = true;
            }
        }
    }
}

/// Keys typed into the catalog filter.
fn typing(mut keys: MessageReader<KeyboardInput>, mut ui: ResMut<Ui>) {
    for key in keys.read() {
        if !ui.typing || !key.state.is_pressed() {
            continue;
        }
        match key.key_code {
            KeyCode::Escape | KeyCode::Enter => ui.typing = false,
            KeyCode::Backspace => {
                ui.filter.pop();
            }
            _ => {
                for c in key.text.iter().flat_map(|t| t.chars()).filter(|c| !c.is_control()) {
                    ui.filter.push(c);
                }
            }
        }
        ui.dirty = true;
    }
}

/// TriggerEditorBehaviour: wait for the keys to come up, then the key released is the binding and a key held with it
/// the secondary; moving the mouse far cancels.
fn rebinding(
    keys: Res<ButtonInput<KeyCode>>,
    mouse: Res<ButtonInput<MouseButton>>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut ui: ResMut<Ui>,
    mut controls: ResMut<Controls>,
    mut files: ResMut<Files>,
    mut from: Local<Option<Vec2>>,
) {
    let Some(i) = ui.rebinding else {
        *from = None;
        return;
    };
    let cursor = window.cursor_position().unwrap_or_default();
    let start = *from.get_or_insert(cursor);
    if (cursor - start).length() > 200.0 {
        ui.rebinding = None;
        ui.dirty = true;
        return;
    }
    let held: Vec<Src> = keys.get_pressed().map(|&k| Src::Key(k)).chain(mouse.get_pressed().map(|&b| Src::Mouse(b))).collect();
    let released = keys.get_just_released().map(|&k| Src::Key(k)).chain(mouse.get_just_released().map(|&b| Src::Mouse(b))).find_map(keys::name);
    if let Some(key) = released {
        let secondary = held.iter().filter_map(|s| keys::name(*s)).last().unwrap_or_else(|| "None".into());
        controls.set(i, &key, &secondary);
        ui.rebinding = None;
        ui.dirty = true;
        files.controls = true;
    }
}

/// The key bound to an action, as the game would test it.
pub fn eval(controls: &Controls, id: &str, inputs: &Inputs) -> crate::game::tool::Control {
    let (key, secondary) = controls.bind(id);
    let Some(k) = keys::src(key) else { return Default::default() };
    let ok = keys::src(secondary).is_none_or(|s| inputs.held(s));
    crate::game::tool::Control { down: inputs.down(k) && ok, held: inputs.held(k) && ok, up: inputs.up(k) }
}

/// The actions the rewrite has nothing behind yet: pressing one says so.
const NOT_REWRITTEN: &[&str] = &[
    "flip", "toggleLimbStatus", "toolInvisibility", "snapToCenter", "copy", "paste", "activateIndirect", "igniteSelection",
    "freezeSelection", "resizeSelection", "arrangeSelection", "toggleThermalVision", "eyedrop", "arrangeDown", "arrangeUp", "arrangeFront",
    "arrangeBack", "incrementGrid", "decrementGrid", "incrementAngleSnap", "decrementAngleSnap",
];

/// The control scheme's UI and time actions.
fn hotkeys(
    keys: Res<ButtonInput<KeyCode>>,
    mouse: Res<ButtonInput<MouseButton>>,
    controls: Res<Controls>,
    time: Res<Time<Real>>,
    mut settings: ResMut<Settings>,
    mut files: ResMut<Files>,
    mut ui: ResMut<Ui>,
    mut queue: ResMut<Queue>,
) {
    let inputs = Inputs { keys: &keys, mouse: &mouse };
    let now = time.elapsed_secs_f64();
    if ui.rebinding.is_some() || ui.typing {
        return;
    }
    let pressed = |id: &str| eval(&controls, id, &inputs).down;
    if pressed("pause") {
        queue.0.push(Act::Escape);
    }
    if ui.mode != Mode::Game {
        return;
    }
    if pressed("time") {
        queue.0.push(Act::TimeToggle);
    }
    if pressed("slowmo") {
        queue.0.push(Act::Slowmo);
    }
    if pressed("toolPowerToggle") {
        queue.0.push(Act::Powers(!ui.powers));
    }
    if pressed("toybox") {
        ui.hide_panels = !ui.hide_panels;
        ui.dirty = true;
    }
    if pressed("toggleUi") {
        ui.hide_ui = !ui.hide_ui;
        ui.dirty = true;
    }
    if pressed("toggleHoveringHighlights") {
        let i = Settings::index("ShowOutlines");
        let v = settings.values[i];
        settings.set(i, 1.0 - v);
        files.settings = true;
    }
    for n in 1..=9 {
        if pressed(&format!("tool{n}")) {
            let list = if ui.powers { POWERS } else { TOOLS };
            match list.iter().filter(|t| t.3.is_empty()).nth(n - 1) {
                Some(t) if t.0 == "Drag" => {}
                Some(t) => ui.toast = Some((format!("{}: not rewritten yet", t.0), now + 2.5)),
                None => {}
            }
        }
    }
    for id in NOT_REWRITTEN {
        if pressed(id) {
            let name = ACTIONS[Controls::index(id)].name;
            ui.toast = Some((format!("{name}: not rewritten yet"), now + 2.5));
        }
    }
}

/// Wheel over a scrolling list.
fn scrolling(
    wheel: Res<AccumulatedMouseScroll>,
    mut lists: Query<(&Scroll, &Hovered, &mut ScrollPosition, &ComputedNode)>,
    mut ui: ResMut<Ui>,
) {
    for (&Scroll(id), hovered, mut pos, node) in &mut lists {
        if hovered.get() && wheel.delta.y != 0.0 {
            let step = if wheel.unit == MouseScrollUnit::Line { 40.0 } else { 1.0 };
            let max = ((node.content_size().y - node.size().y) * node.inverse_scale_factor()).max(0.0);
            pos.y = (pos.y - wheel.delta.y * step).clamp(0.0, max);
        }
        if ui.scroll.get(&id) != Some(&pos.y) {
            ui.scroll.insert(id, pos.y);
        }
    }
}

// ---------------------------------------------------------------- actions

fn apply(
    mut queue: ResMut<Queue>,
    mut ui: ResMut<Ui>,
    mut settings: ResMut<Settings>,
    mut controls: ResMut<Controls>,
    mut files: ResMut<Files>,
    time: Res<Time<Real>>,
    mut exit: MessageWriter<AppExit>,
    mut commands: Commands,
    mut play: Option<ResMut<Play>>,
    sprites: Query<Entity, Or<(With<play::LimbSprite>, With<play::ObjectSprite>, With<play::RendererSprite>)>>,
) {
    let now = time.elapsed_secs_f64();
    for act in std::mem::take(&mut queue.0) {
        match &act {
            // ClearDebrisBehaviour.Clear / ClearLivingBehaviour.Clear.
            Act::ClearMess | Act::ClearLiving if ui.mode == Mode::Game => {
                if let Some(p) = play.as_deref_mut() {
                    match act {
                        Act::ClearMess => p.game.clear_debris(),
                        _ => p.game.clear_living(),
                    }
                }
            }
            Act::Set(i, v) => {
                settings.set(*i, *v);
                files.settings = true;
            }
            Act::Rebind(i) => {
                ui.rebinding = Some(*i);
                ui.dirty = true;
            }
            Act::Unbind(i) => {
                controls.set(*i, "None", "None");
                files.controls = true;
                ui.dirty = true;
            }
            Act::ResetControls => {
                *controls = Controls::default();
                files.controls = true;
                ui.dirty = true;
            }
            Act::Nav(Page::Maps) if ui.maps.is_empty() => match data::maps(&ui.game) {
                Ok(maps) => ui.maps = maps.into_iter().map(|m| MapRow { name: m.name, description: m.description }).collect(),
                Err(e) => ui.error = Some(e),
            },
            _ => {}
        }
        let effect = ui.press(&act, now);
        // Leaving a game: the tutorial flag the simulation clears is a preference.
        if let (Some(p), true) = (&play, effect != Effect::None) {
            let (i, v) = (Settings::index("ShowTutorial"), p.game.prefs.ShowTutorial as i32 as f32);
            if settings.values[i] != v {
                settings.values[i] = v;
                files.settings = true;
            }
        }
        match effect {
            Effect::Quit => {
                exit.write(AppExit::Success);
            }
            Effect::ToMenu => {
                for e in &sprites {
                    commands.entity(e).despawn();
                }
                commands.remove_resource::<Play>();
            }
            Effect::Load(_) | Effect::None => {}
        }
    }
}

/// Loads the map on the second frame of the "Loading" page.
fn loading(
    mut ui: ResMut<Ui>,
    settings: Res<Settings>,
    mut commands: Commands,
    mut frames: Local<u8>,
    sprites: Query<Entity, Or<(With<play::LimbSprite>, With<play::ObjectSprite>, With<play::RendererSprite>)>>,
    mut camera: Single<(&mut Transform, &mut Projection), With<Camera2d>>,
) {
    if ui.mode != Mode::Loading {
        *frames = 0;
        return;
    }
    *frames += 1;
    if *frames < 3 {
        return;
    }
    *frames = 0;
    let Some(map) = ui.map.clone() else { return };
    let result = play::guarded(|| {
        // The player seeds UnityEngine.Random from the clock at startup, so each session differs; tests keep seed 0.
        let seed = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_nanos() as i32);
        let mut g = play::new_game(&ui.game, &map, ui.item.as_deref(), Some(settings.prefs()), seed)?;
        let catalog = match g.assets.as_deref_mut() {
            Some(db) => data::catalog(db)?,
            None => Default::default(),
        };
        Ok((g, catalog))
    });
    match result {
        Ok((game, catalog)) => {
            for e in &sprites {
                commands.entity(e).despawn();
            }
            camera.0.translation = centre(&game);
            *camera.1 = Projection::Orthographic(OrthographicProjection { scale: 0.006, ..OrthographicProjection::default_2d() });
            ui.catalog = catalog;
            ui.category = 0;
            commands.insert_resource(Play::new(game));
            ui.started();
        }
        Err(e) => ui.failed(e),
    }
}

/// A game that started with the app (--play-map) lists its catalog once.
fn late_catalog(mut ui: ResMut<Ui>, mut play: Option<ResMut<Play>>, mut tried: Local<bool>) {
    let Some(play) = play.as_deref_mut() else {
        *tried = false;
        return;
    };
    if *tried || ui.mode != Mode::Game || !ui.catalog.categories.is_empty() {
        return;
    }
    *tried = true;
    match play.game.assets.as_deref_mut().map(data::catalog) {
        Some(Ok(c)) => ui.catalog = c,
        Some(Err(e)) => ui.error = Some(e),
        None => {}
    }
    ui.dirty = true;
}

// ---------------------------------------------------------------- the view

fn rebuild(
    mut commands: Commands,
    mut ui: ResMut<Ui>,
    settings: Res<Settings>,
    controls: Res<Controls>,
    play: Option<Res<Play>>,
    roots: Query<Entity, With<Root>>,
    mut shown_stopped: Local<bool>,
) {
    let stopped = play.as_ref().and_then(|p| p.stopped.as_deref());
    if stopped.is_some() != *shown_stopped {
        *shown_stopped = stopped.is_some();
        ui.dirty = true;
    }
    if !ui.dirty {
        return;
    }
    ui.dirty = false;
    for e in &roots {
        commands.entity(e).despawn();
    }
    build(&mut commands, &ui, &settings, &controls, stopped);
}

/// Texts, colours and slider fills that follow the state without a rebuild.
fn live(
    time: Res<Time<Real>>,
    ui: Res<Ui>,
    settings: Res<Settings>,
    controls: Res<Controls>,
    play: Option<Res<Play>>,
    mut fps: ResMut<Fps>,
    tips: Query<(&Tip, &Hovered)>,
    mut texts: Query<(&Bound, &mut Text)>,
    mut looks: Query<(&Look, &Hovered, &mut BackgroundColor)>,
    mut fills: Query<(&FillOf, &mut Node)>,
) {
    let now = time.elapsed_secs_f64();
    fps.frames += 1;
    fps.time += time.delta_secs();
    if fps.time >= 1.0 {
        fps.shown = (fps.frames as f32 / fps.time).round() as u32;
        (fps.frames, fps.time) = (0, 0.0);
    }
    let tip = tips.iter().filter(|(_, h)| h.get()).map(|(t, _)| t.0.as_str()).find(|t| !t.is_empty()).unwrap_or("");
    let scale = play.as_ref().map_or(1.0, |p| p.game.time.timeScale);
    let mut status = format!("Tool: Drag   Time: {}%", (scale * 100.0).round());
    if settings.flag("ShowFramerate") {
        status += &format!("   {} fps", fps.shown);
    }
    if let Some(p) = &play {
        if p.stopped.is_none() && ui.paused {
            status += "   PAUSED";
        }
    }
    let toast = ui.toast.as_ref().filter(|(_, until)| *until > now).map_or("", |(t, _)| t.as_str());
    for (bound, mut text) in &mut texts {
        let s = match bound {
            Bound::Setting(i) => settings.text(*i),
            Bound::Bind(i) => if ui.rebinding == Some(*i) { "Press any button...".into() } else { controls.text(*i) },
            Bound::Status => status.clone(),
            Bound::Tip => tip.to_string(),
            Bound::Toast => toast.to_string(),
            Bound::Filter => format!("Filter: {}{}", ui.filter, if ui.typing { "_" } else { "" }),
        };
        if text.0 != s {
            text.0 = s;
        }
    }
    for (look, hovered, mut bg) in &mut looks {
        let selected = look.sel.selected(&ui, &settings, &controls);
        let c = look.colour(selected, hovered.get(), &ui, &controls);
        if bg.0 != c {
            bg.0 = c;
        }
    }
    for (&FillOf(i), mut node) in &mut fills {
        node.width = percent(settings.fraction(i) * 100.0);
    }
}

/// Preferences and controls to disk, once the mouse is up.
fn save(mut files: ResMut<Files>, settings: Res<Settings>, controls: Res<Controls>, mouse: Res<ButtonInput<MouseButton>>) {
    if mouse.pressed(MouseButton::Left) {
        return;
    }
    if files.settings {
        files.settings = false;
        if let Err(e) = std::fs::write(files.settings_path(), settings.json()) {
            eprintln!("preferences not saved: {e}");
        }
    }
    if files.controls {
        files.controls = false;
        if let Err(e) = std::fs::write(files.controls_path(), controls.json()) {
            eprintln!("controls not saved: {e}");
        }
    }
}

/// VSync and Window mode.
fn window(settings: Res<Settings>, mut window: Single<&mut Window, With<PrimaryWindow>>) {
    if !settings.is_changed() {
        return;
    }
    let present = if settings.flag("VSync") { PresentMode::AutoVsync } else { PresentMode::AutoNoVsync };
    if window.present_mode != present {
        window.present_mode = present;
    }
    let mode = match settings.get("WindowMode") as i32 {
        0 => WindowMode::Windowed,
        1 => WindowMode::BorderlessFullscreen(MonitorSelection::Current),
        _ => WindowMode::Fullscreen(MonitorSelection::Current, VideoModeSelection::Current),
    };
    if window.mode != mode {
        window.mode = mode;
    }
}

// ---------------------------------------------------------------- the game under it

/// Pan (middle drag and the arrow keys) and zoom (wheel and +/-).
fn camera(
    keys: Res<ButtonInput<KeyCode>>,
    mouse: Res<ButtonInput<MouseButton>>,
    controls: Res<Controls>,
    settings: Res<Settings>,
    motion: Res<AccumulatedMouseMotion>,
    wheel: Res<AccumulatedMouseScroll>,
    time: Res<Time<Real>>,
    ui: Res<Ui>,
    hover: Res<HoverMap>,
    nodes: Query<(), With<Node>>,
    mut camera: Single<(&mut Transform, &mut Projection), With<Camera2d>>,
    mut panning: Local<bool>,
) {
    if ui.mode != Mode::Game || ui.typing {
        *panning = false;
        return;
    }
    let inputs = Inputs { keys: &keys, mouse: &mouse };
    let over = over_ui(&hover, &nodes);
    let (transform, projection) = &mut *camera;
    let Projection::Orthographic(o) = &mut **projection else { return };
    let pan = eval(&controls, "pan", &inputs);
    if pan.down && !over {
        *panning = true;
    }
    if !pan.held {
        *panning = false;
    }
    if *panning {
        transform.translation += Vec3::new(-motion.delta.x, motion.delta.y, 0.0) * o.scale;
    }
    let dt = time.delta_secs();
    let held = |id: &str| eval(&controls, id, &inputs).held as i32 as f32;
    let dir = Vec2::new(held("panRight") - held("panLeft"), held("panUp") - held("panDown"));
    transform.translation += (dir * 700.0 * o.scale * dt).extend(0.0);
    let mut zoom = (held("zoomOut") - held("zoomIn")) * dt;
    if !over && wheel.delta.y != 0.0 {
        let lines = if wheel.unit == MouseScrollUnit::Line { wheel.delta.y } else { wheel.delta.y / 40.0 };
        zoom -= lines * 0.12 * settings.get("ZoomSensitivity");
    }
    o.scale = (o.scale * zoom.exp()).clamp(0.0008, 0.05);
}

/// One frame of the game, under Global's time scale: paused or slowed by the toolbar, 0 in the pause menu.
fn game_frame(time: Res<Time<Real>>, mut ui: ResMut<Ui>, settings: Res<Settings>, mut play: ResMut<Play>) {
    if ui.mode == Mode::Loading || play.stopped.is_some() {
        return;
    }
    let real = time.delta_secs();
    // Time.timeScale is stepped from the unscaled delta once the frame is done, so it applies from the next one.
    if ui.mode == Mode::Game && play.game.time.timeScale >= 1.0e-3 {
        // ponytail: below 0.001 the frame is skipped; Unity still runs the Update scripts at a zero scale.
        if let Err(m) = play::step(&mut play.game, real) {
            play.stopped = Some(m);
            return;
        }
    }
    // NotificationControllerBehaviour.Show: the last text stays up for a moment (the rich text's tags are not drawn).
    if let Some(n) = play.game.notifications.drain(..).last() {
        ui.toast = Some((n.replace("<b>", "").replace("</b>", ""), time.elapsed_secs_f64() + 2.5));
    }
    let target = time_scale_target(ui.paused || ui.mode != Mode::Game, ui.slowmo, settings.get("SlowMotionSpeed"));
    let t = &mut play.game.time.timeScale;
    *t = smooth_approach(*t, target, 15.0, real);
}

/// The cursor and the control scheme as the game's Input: the mouse position through this window's camera, and the
/// controls the simulation reads, for presses that began where the world may take them.
fn world_input(
    buttons: Res<ButtonInput<MouseButton>>,
    keys: Res<ButtonInput<KeyCode>>,
    controls: Res<Controls>,
    mut ui: ResMut<Ui>,
    hover: Res<HoverMap>,
    nodes: Query<(), With<Node>>,
    window: Single<&Window, With<PrimaryWindow>>,
    camera: Single<(&Camera, &GlobalTransform)>,
    mut play: ResMut<Play>,
    mut owned: Local<std::collections::HashMap<&'static str, bool>>,
) {
    let (camera, at) = *camera;
    let size = window.size();
    let (Ok(origin), Ok(one)) = (camera.viewport_to_world_2d(at, Vec2::new(0.0, size.y)), camera.viewport_to_world_2d(at, Vec2::new(1.0, size.y))) else { return };
    let input = &mut play.game.input;
    if let (Ok(min), Ok(max)) = (camera.viewport_to_world_2d(at, Vec2::new(0.0, size.y)), camera.viewport_to_world_2d(at, Vec2::new(size.x, 0.0))) {
        input.view = Some((min.to_array(), max.to_array()));
    }
    if let Some(c) = window.cursor_position() {
        // Unity's screen y runs up from the bottom.
        let pixel = [c.x, size.y - c.y];
        let screen = crate::game::tool::Screen { mouse: pixel, origin: origin.to_array(), scale: one.x - origin.x };
        let w = screen.to_world(pixel);
        input.mouse = [w[0], w[1], 0.0];
        input.screen = Some(screen);
    }
    let inputs = Inputs { keys: &keys, mouse: &buttons };
    let over = over_ui(&hover, &nodes);
    let now = ui.mode == Mode::Game && !ui.typing && ui.rebinding.is_none();
    let start = now && ui.context.is_none();
    // The only controls the simulation reads; the others (flip, copy, the other tools) are not rewritten there.
    for id in ["drag", "context", "fast", "snap", "left", "right", "activateDirect", "spawnLeft", "spawnRight", "delete", "undo"] {
        let own = owned.entry(id).or_default();
        let from_mouse = matches!(keys::src(&controls.bind(id).0), Some(Src::Mouse(_)));
        let allowed = if *own { now } else { start && !(from_mouse && over) };
        let c = gate(own, eval(&controls, id, &inputs), allowed);
        if id == "context" && c.up {
            ui.context = window.cursor_position().map(|c| c.to_array());
            ui.dirty = true;
        }
        play.game.input.controls.insert(id.into(), c);
    }
    if play.game.catalog_selected != ui.item {
        play.game.catalog_selected = ui.item.clone();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The menu's systems and widgets on a headless app: no window, no renderer.
    fn app() -> App {
        std::fs::create_dir_all(std::env::temp_dir().join("ppr-ui-test")).unwrap();
        let mut app = App::new();
        app.add_plugins((MinimalPlugins, bevy::input::InputPlugin)).init_resource::<HoverMap>();
        app.world_mut().spawn((Window::default(), PrimaryWindow));
        let rows = ["Default", "Arena"].map(|n| MapRow { name: n.into(), description: String::new() });
        let mut ui = new_ui(None, Mode::Menu, None, None);
        ui.maps = rows.into();
        app.insert_resource(ui)
            .insert_resource(Settings::default())
            .insert_resource(Controls::default())
            .insert_resource(Files { dir: std::env::temp_dir().join("ppr-ui-test"), settings: false, controls: false });
        add(&mut app);
        app
    }

    fn count<T: Component>(app: &mut App) -> usize {
        app.world_mut().query::<&T>().iter(app.world()).count()
    }

    #[test]
    fn menu_pages_build_and_settings_apply() {
        let mut app = app();
        app.update();
        // The main menu: Play, Settings, Mods, Information, Quit.
        assert_eq!(count::<Press>(&mut app), 5);
        app.world_mut().resource_mut::<Queue>().0.push(Act::Nav(Page::Settings));
        app.update();
        app.update();
        // General: five sliders; the tab column (6 categories + Controls + Back) and the radio buttons.
        assert_eq!(count::<SliderOf>(&mut app), 5);
        let i = Settings::index("GorelessMode");
        app.world_mut().resource_mut::<Queue>().0.push(Act::Tab(1));
        app.world_mut().resource_mut::<Queue>().0.push(Act::Set(i, 1.0));
        app.update();
        app.update();
        assert!(app.world().resource::<Settings>().flag("GorelessMode"));
        let saved = std::fs::read_to_string(std::env::temp_dir().join("ppr-ui-test/ppr-preferences.json")).unwrap();
        assert!(saved.contains("\"GorelessMode\": true"), "saved once the mouse is up");
        assert_eq!(count::<SliderOf>(&mut app), 2, "Gore: fragility and crush sensitivity");
        app.world_mut().resource_mut::<Queue>().0.push(Act::Nav(Page::Controls));
        app.update();
        app.update();
        let visible = ACTIONS.iter().filter(|a| ACTION_CATEGORIES.contains(&a.category) && !a.invisible).count();
        assert_eq!(count::<Bound>(&mut app) - 2, visible, "a binding text per listed action");
        app.world_mut().resource_mut::<Queue>().0.push(Act::Nav(Page::Maps));
        app.update();
        app.update();
        let text = |app: &mut App| app.world_mut().query::<&Text>().iter(app.world()).map(|t| t.0.clone()).collect::<Vec<_>>();
        assert!(text(&mut app).contains(&"Select a chamber".to_string()));
        app.world_mut().resource_mut::<Queue>().0.push(Act::SelectMap(1));
        app.update();
        app.update();
        assert!(text(&mut app).contains(&"Enter Arena".to_string()));
        std::fs::remove_dir_all(std::env::temp_dir().join("ppr-ui-test")).ok();
    }

    /// Plays a real map under the UI: load, frames, reset and back to the menu (cargo test -- --ignored).
    #[test]
    #[ignore]
    fn the_installed_game_loads_resets_and_leaves() {
        let game = crate::game_assets::find_game(None).unwrap();
        let cache = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("local-cache");
        let mut app = app();
        app.add_plugins(AssetPlugin { file_path: cache.to_string_lossy().into_owned(), ..default() })
            .init_asset::<Image>()
            .init_resource::<bevy::gizmos::config::GizmoConfigStore>()
            .insert_resource(crate::game_assets::HumanRig::load(&cache, &game).unwrap());
        app.world_mut().resource_mut::<bevy::gizmos::config::GizmoConfigStore>().insert(default(), bevy::gizmos::config::DefaultGizmoConfigGroup);
        app.world_mut().resource_mut::<Ui>().game = game.clone();
        // The game's own config.json (a fresh install would play the tutorial, which is not rewritten).
        app.world_mut().resource_mut::<Settings>().load(&std::fs::read_to_string(game.join("config.json")).unwrap_or_default());
        let maps = data::maps(&game).unwrap();
        let default = maps.iter().position(|m| m.name == "Default").unwrap();
        app.world_mut().resource_mut::<Ui>().maps = maps.into_iter().map(|m| MapRow { name: m.name, description: m.description }).collect();
        let queue = |app: &mut App, a: Act| app.world_mut().resource_mut::<Queue>().0.push(a);
        queue(&mut app, Act::SelectMap(default));
        queue(&mut app, Act::Enter);
        for _ in 0..8 {
            app.update();
        }
        assert_eq!(app.world().resource::<Ui>().mode, Mode::Game, "{:?}", app.world().resource::<Ui>().error);
        let first = app.world().resource::<Play>().game.time.frameCount;
        for _ in 0..30 {
            app.update();
        }
        let play = app.world().resource::<Play>();
        assert!(play.game.time.frameCount > first && play.stopped.is_none(), "{:?}", play.stopped);
        let shown = app.world().resource::<Ui>().catalog.shown(0, "").len();
        assert!(shown > 0);
        assert_eq!(count::<play::LimbSprite>(&mut app), app.world().resource::<Play>().game.limbs.len());
        let limbs = count::<play::LimbSprite>(&mut app);
        // Reset: a new game with fresh sprites, none left over.
        queue(&mut app, Act::Escape);
        queue(&mut app, Act::Restart);
        for _ in 0..8 {
            app.update();
        }
        assert_eq!(app.world().resource::<Ui>().mode, Mode::Game);
        assert_eq!(count::<play::LimbSprite>(&mut app), limbs);
        // Back to the menu: the game and its sprites are gone.
        queue(&mut app, Act::Escape);
        queue(&mut app, Act::ToMenu);
        app.update();
        app.update();
        assert!(app.world().get_resource::<Play>().is_none());
        assert_eq!(count::<play::LimbSprite>(&mut app), 0);
        assert_eq!(app.world().resource::<Ui>().mode, Mode::Menu);
    }
}
